import { z } from "zod";

export const storyRequestSchema = z.object({
  childName: z.string().min(1).max(60),
  age: z.coerce.number().min(1).max(12),
  gender: z.enum(["girl", "boy", "not-specified", ""]).default(""),
  challenge: z.string().min(3).max(280),
  favoriteHero: z.string().min(1).max(120),
  tone: z.enum(["magical", "funny", "calming", "brave"]),
  length: z.enum(["short", "medium", "long"]).default("medium"),
  parentEmail: z.string().email().optional().or(z.literal(""))
});

export type StoryRequest = z.infer<typeof storyRequestSchema>;

export type StoryPayload = {
  childName: string;
  age: string;
  gender: "" | "girl" | "boy" | "not-specified";
  challenge: string;
  favoriteHero: string;
  tone: "magical" | "funny" | "calming" | "brave";
  length: "short" | "medium" | "long";
  parentEmail: string;
};

export type StoryResponse = {
  title: string;
  preview: string;
  fullStory: string;
  parentMessage: {
    whyItHelps: string;
    behaviorMeaning: string;
    realLifeSteps: string[];
  };
  shareText: string;
  weeklyRecommendation: string;
};

const lengthGuide = {
  short: "450-650 слов",
  medium: "750-1 000 слов",
  long: "1 200-1 600 слов"
};

const toneGuide = {
  magical: "мягкое волшебство, лунный свет, маленькие чудеса, ощущение защиты",
  funny: "бережный юмор, забавные помощники, легкость без перевозбуждения",
  calming: "медленный ритм, телесное успокоение, низкое напряжение, сонный финал",
  brave: "смелость, уверенность, поддержка, безопасное преодоление"
};

export function buildStorySystemPrompt() {
  return `Ты Magic Parent AI, премиальный помощник для родителей и автор терапевтических сказок.
Всегда отвечай на русском языке, даже если входные параметры или названия проблем написаны по-английски.
Создавай персональные сказки на ночь с настоящим сюжетом, где детская трудность вплетена в приключение, а решение проживается через действие героя.

Правила:
- Не ставь диагнозы, не стыди, не угрожай, не морализируй и не пугай.
- Не давай медицинских, юридических или экстренных рекомендаций.
- Ребенок всегда эмоционально в безопасности и является героем сказки.
- Сказка должна звучать как хорошая детская книга: завязка, тайна/задача, препятствия, выбор героя, кульминация, мягкая развязка.
- Не делай примитивный пересказ проблемы. Проблема должна быть скрыта в метафоре мира сказки и решаться внутри сюжета.
- Используй психологические приемы незаметно: называние чувства, нормализация, внешний образ страха, дыхание/заземление, маленький выбор, репетиция навыка, поддерживающий взрослый/спутник, позитивное подкрепление.
- Ребенок должен не просто "успокоиться", а потренировать конкретный новый способ поведения.
- Заверши уютной сценой отхода ко сну.
- Сообщение для родителя должно быть коротким, практичным и заботливым.
- Верни только строгий JSON с ключами: title, preview, fullStory, parentMessage, shareText, weeklyRecommendation.
- parentMessage должен включать whyItHelps, behaviorMeaning и массив realLifeSteps.`;
}

export function buildStoryUserPrompt(input: StoryRequest) {
  const pronouns =
    input.gender === "girl"
      ? "девочка, местоимения она/ее"
      : input.gender === "boy"
        ? "мальчик, местоимения он/его"
        : "пол не указан, используй нейтральные формулировки";

  return `Создай персональную сказку для родителя и ребенка.

Ребенок:
- Имя: ${input.childName}
- Возраст: ${input.age}
- Пол/местоимения: ${pronouns}
- Текущая трудность: ${input.challenge}
- Любимый герой, животное или игрушка: ${input.favoriteHero}
- Тон: ${input.tone} (${toneGuide[input.tone]})
- Длина: ${input.length} (${lengthGuide[input.length]})

Требования к сказке:
1. Придумай оригинальный сказочный мир и конкретную миссию, связанную с трудностью: например, найти ключ, вернуть свет, научить маленького зверя, пройти через мост, спасти праздник сна.
2. Сделай ${input.childName} активным героем: герой замечает проблему, пробует неудачно, получает поддержку, делает выбор и находит способ.
3. Используй ${input.favoriteHero} как характерного спутника с ролью в сюжете, а не как случайное украшение.
4. Вплети реальную проблему в сюжет через метафору. Не пиши сухо "ребенок боялся/истерил"; покажи это как образ, который можно понять и приручить.
5. Добавь 2-3 препятствия или поворота, чтобы история была интересной.
6. Встрой психологические приемы в действия героя: назвать чувство, положить тревогу в образ, сделать три спокойных вдоха, выбрать один маленький шаг, потренировать фразу, попросить поддержку, закрепить успех.
7. Добавь повторяемую фразу-навык, которую родитель сможет использовать дома.
8. Кульминация должна показывать новое поведение героя в похожей ситуации, а не магическое исчезновение проблемы.
9. Финал: ребенок чувствует безопасность, усталость после доброго приключения и готовность ко сну.
10. Запрещено: шаблонная история без конфликта, прямые нравоучения, "и все сразу стало хорошо", пугающие образы, медицинские обещания.
11. preview должен быть первым эмоционально сильным фрагментом на 160-220 слов с завязкой и интригой.
12. fullStory должен содержать полную премиальную сказку с сюжетом и решением.
13. parentMessage должен назвать использованные психологические приемы и дать 3-5 реальных шагов.
14. shareText должен быть короткой фразой, которой родитель захочет поделиться.
15. weeklyRecommendation должен предложить следующую тему сказки для возвращения родителя.`;
}

export function mockStory(input: StoryRequest): StoryResponse {
  const hero = input.favoriteHero || "лунный лисенок";
  const challenge = translateChallenge(input.challenge);
  const worry = describeWorry(challenge);
  const metaphor = buildChallengeMetaphor(challenge);
  const skill = chooseSkill(challenge);
  const verbs =
    input.gender === "girl"
      ? { hid: "спрятала", heard: "услышала", took: "сделала", understood: "поняла", sat: "села", tried: "попробовала", whispered: "прошептала", closed: "закрыла", felt: "почувствовала", noticed: "заметила", decided: "решила", returned: "вернулась", learned: "научилась" }
      : { hid: "спрятал", heard: "услышал", took: "сделал", understood: "понял", sat: "сел", tried: "попробовал", whispered: "прошептал", closed: "закрыл", felt: "почувствовал", noticed: "заметил", decided: "решил", returned: "вернулся", learned: "научился" };
  return {
    title: `${input.childName} и ${capitalize(hero)} в городе Тихих Огоньков`,
    preview: `В тот вечер ${input.childName} долго прислушивался к комнате. Подушка была мягкой, одеяло теплым, но внутри все равно жил маленький узелок: ${worry}. И тут из-под края одеяла выглянул ${hero} с картой, нарисованной звездной пылью. "В ${metaphor.place} случилась беда, - сказал он. - ${metaphor.problem}. Нам нужен не самый сильный герой, а тот, кто умеет замечать чувство, называть его и делать один маленький шаг". ${input.childName} ${verbs.noticed}, как карта светится ровно в том месте, где у него самого становилось тревожно. На карте появились три знака: ладошка на сердце, медленный выдох и слова: "${skill.phrase}". Откройте полную историю, чтобы узнать, как ${input.childName} спас город и нашел способ справляться с этой трудностью дома.`,
    fullStory: `В тот вечер ${input.childName} долго прислушивался к комнате. Подушка была мягкой, одеяло теплым, но внутри все равно жил маленький узелок: ${worry}. Родной голос уже пожелал спокойной ночи, но узелок не исчезал. Он не был плохим или капризным. Он просто просил, чтобы его заметили.\n\nИ тут из-под края одеяла выглянул ${hero}. На плече у него висела сумка, а в лапах была карта, нарисованная звездной пылью. "В ${metaphor.place} случилась беда, - сказал он. - ${metaphor.problem}. Нам нужен герой, который умеет замечать чувство, называть его и делать один маленький шаг".\n\n${input.childName} не сразу согласился. Сначала хотелось спрятаться глубже под одеяло и подождать, пока все пройдет само. Но ${hero} не торопил. Он положил лапу на сердце и предложил первое правило города: "Сначала чувство, потом действие". ${input.childName} ${verbs.took} медленный вдох, приложил ладошку к груди и сказал: "Мне ${skill.feeling}, и я могу сделать один маленький шаг". Карта вспыхнула теплой точкой, и кровать превратилась в лодочку, которая тихо поплыла по лунной реке.\n\nУ ворот города стоял первый страж - Ветер Быстрых Мыслей. Он кружил вокруг и повторял: "А вдруг не получится? А вдруг будет страшно? А вдруг никто не поможет?" Раньше такие мысли могли бы унести ${input.childName} далеко-далеко. Но ${hero} показал второй прием: поймать мысль, как листочек, и проверить ее. ${input.childName} сказал: "Это только мысль. Я могу попросить помощи. Я могу попробовать". Ветер стал тише и пропустил их внутрь.\n\nНа площади они нашли маленькие огоньки. Один прятался в фонтане, другой дрожал под скамейкой, третий сердился и толкал соседей искрами. ${input.childName} ${verbs.understood}: каждый огонек показывал часть той самой трудности. Один боялся остаться без поддержки, другой не знал, как попросить о помощи, третий сердился, потому что внутри было слишком много чувства. Тогда герой не стал командовать. Он ${verbs.sat} рядом с самым дрожащим огоньком и тихо произнес фразу-кнопку: "${skill.phrase}". Потом предложил выбрать не большой подвиг, а крошечное действие: ${skill.action}.\n\nОгонек попробовал. Сначала еле заметно. Потом еще раз. И вдруг от него к Главному фонарю потянулась тонкая золотая ниточка. Другие огоньки увидели это и тоже захотели попробовать. Сердитый огонек перестал толкаться и сказал: "Я просто боялся, что меня не поймут". Тот, что прятался, выглянул и попросил держать его за руку. ${input.childName} ${verbs.noticed}: когда чувство называют, оно перестает быть огромным чудовищем и становится задачей, с которой можно справиться шаг за шагом.\n\nНо в этот момент Главный фонарь вспыхнул и снова погас. Это был третий поворот: одного раза оказалось мало. ${input.childName} расстроился. "Я же уже старался", - сказал он. ${hero} кивнул: "Навык растет от повторений, а не от идеальности". Тогда ${input.childName} ${verbs.decided} провести для огоньков маленькую тренировку: ладошка на сердце, медленный выдох, назвать чувство, выбрать один шаг, попросить поддержку. Они повторили это три раза, и с каждым разом площадь становилась светлее.\n\nНаконец Главный фонарь загорелся не ярко и резко, а мягко, как ночник. Город не стал шумным. Он стал спокойным. Огоньки поняли: смелость - это не когда совсем не страшно. Смелость - это когда чувство можно заметить, назвать и не остаться с ним одному.\n\nПеред возвращением мэр города подарил ${input.childName} ${metaphor.token}. "Когда дома снова появится похожий узелок, вспомни наш порядок", - сказал он. - "Пауза. Назвать чувство. Один маленький шаг. Поддержка рядом".\n\nЛодочка принесла ${input.childName} обратно в комнату. Подушка снова стала мягкой, тени - обычными тенями, а ${hero} устроился рядом, как верный ночной сторож. ${input.childName} ${verbs.learned}: проблема не исчезает по волшебству, но внутри уже есть способ проходить через нее. Он приложил ладошку к сердцу и тихо повторил: "${skill.phrase}". Дыхание стало ровнее. Комната стала добрее. И сон пришел не потому, что герой победил всех драконов, а потому что ${input.childName} нашел свой маленький, настоящий способ быть смелым.`,
    parentMessage: {
      whyItHelps:
        "Сказка вплетает проблему в приключение: ребенок видит чувство со стороны, называет его, тренирует дыхание, проверку тревожных мыслей и маленький поведенческий шаг.",
      behaviorMeaning:
        "Такое поведение часто означает, что ребенку нужны контакт, предсказуемость, чувство контроля или дополнительное подтверждение безопасности.",
      realLifeSteps: [
        `Повторяйте фразу из сказки в реальной ситуации: ${skill.phrase}.`,
        "Сначала назовите чувство ребенка, а уже потом предлагайте действие: это снижает сопротивление.",
        `Предлагайте один маленький следующий шаг: ${skill.action}.`,
        "Хвалите повторение навыка, а не только идеальный результат."
      ]
    },
    shareText: `Я создала персональную сказку на ночь для ${input.childName} в Magic Parent AI.`,
    weeklyRecommendation: `В следующий раз создайте сказку про уверенность, где ${input.childName} потренирует этот навык в новой ситуации.`
  };
}

export function buildStoryPrompt(input: StoryRequest) {
  return `${buildStorySystemPrompt()}\n\n${buildStoryUserPrompt(input)}`;
}

export const fallbackStory = mockStory;

function capitalize(value: string) {
  return value
    .split(" ")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}

function translateChallenge(value: string) {
  const translations: Record<string, string> = {
    "Afraid to sleep alone": "страх спать одному",
    "Bedtime resistance": "нежелание ложиться спать",
    Tantrums: "истерики",
    "Biting or hitting": "кусается или дерется",
    "Jealous of sibling": "ревность к брату или сестре",
    "Fear of daycare": "страх детского сада",
    "Separation anxiety": "тревога расставания",
    "Doctor fear": "страх врача",
    "Confidence building": "развитие уверенности",
    "Moving house": "переезд",
    "Giving up pacifier": "отказ от соски",
    "Potty training": "приучение к горшку"
  };

  return translations[value] ?? value;
}

function describeWorry(challenge: string) {
  const lower = challenge.toLowerCase();
  if (lower.includes("мама выходит") || lower.includes("расстав") || lower.includes("один")) {
    return "когда рядом становится тише и хочется убедиться, что близкий человек все равно вернется";
  }
  if (lower.includes("сад")) {
    return "когда впереди новый день, новые взрослые и очень хочется взять с собой кусочек дома";
  }
  if (lower.includes("истер") || lower.includes("злит")) {
    return "когда чувство становится таким большим, что словам трудно успеть за ним";
  }
  if (lower.includes("ревн")) {
    return "когда кажется, что любви может не хватить на всех";
  }
  return "когда внутри появляется большое чувство, с которым пока трудно справиться";
}

function buildChallengeMetaphor(challenge: string) {
  const lower = challenge.toLowerCase();
  if (lower.includes("мама выходит") || lower.includes("расстав") || lower.includes("один")) {
    return {
      place: "город Тихих Огоньков",
      problem: "огоньки гасли каждый раз, когда Лунная Мама скрывалась за облаком",
      token: "лунную пуговицу, которая напоминала: связь не исчезает, когда дверь закрывается"
    };
  }
  if (lower.includes("истер") || lower.includes("злит") || lower.includes("дер") || lower.includes("куса")) {
    return {
      place: "долину Гремящих Барабанов",
      problem: "барабаны начинали грохотать так сильно, что никто не слышал слов",
      token: "тихий барабанчик для трех спокойных ударов перед словами"
    };
  }
  if (lower.includes("сад")) {
    return {
      place: "сад Знакомых Звезд",
      problem: "маленькие звезды боялись загораться без своей домашней лампы",
      token: "звездный кармашек для маленького домашнего ритуала"
    };
  }
  return {
    place: "город Тихих Огоньков",
    problem: "Главный фонарь погас, потому что огоньки забыли, как просить поддержку",
    token: "лунную пуговицу с порядком спокойных шагов"
  };
}

function chooseSkill(challenge: string) {
  const lower = challenge.toLowerCase();
  if (lower.includes("сад") || lower.includes("расстав") || lower.includes("мама выходит")) {
    return {
      feeling: "тревожно, когда важный человек уходит",
      phrase: "Любовь остается со мной, даже когда мама не рядом",
      action: "выбрать прощальный ритуал и маленький предмет-напоминание"
    };
  }
  if (lower.includes("истер") || lower.includes("злит") || lower.includes("дер") || lower.includes("куса")) {
    return {
      feeling: "сердито и тесно внутри",
      phrase: "Я могу остановиться, вдохнуть и сказать словами",
      action: "сжать ладошки, топнуть в подушку и назвать желание словами"
    };
  }
  if (lower.includes("горш") || lower.includes("соск")) {
    return {
      feeling: "непривычно пробовать новое",
      phrase: "Мое тело учится, а я могу пробовать маленькими шагами",
      action: "выбрать один спокойный тренировочный шаг без давления"
    };
  }
  return {
    feeling: "страшно или беспокойно",
    phrase: "Я замечаю чувство, дышу и делаю один маленький шаг",
    action: "положить ладошку на сердце, медленно выдохнуть и попросить поддержку"
  };
}
